class Solution {
public:
    long long numberOfPowerfulInt(long long start, long long finish, int limit, string s) {
        long long sv = stoll(s);
        auto count = [&](long long x) -> long long {
            if (x < sv) return 0;
            string xs = to_string(x);
            int n = (int)xs.size();
            int m = (int)s.size();
            if (n < m) return 0;
            int k = n - m;
            vector<long long> powv(k + 1);
            powv[0] = 1;
            for (int i = 1; i <= k; i++) powv[i] = powv[i - 1] * (limit + 1);
            long long result = 0;
            bool tight = true;
            for (int i = 0; i < k && tight; i++) {
                int digit = xs[i] - '0';
                if (digit > limit) {
                    result += (long long)(limit + 1) * powv[k - 1 - i];
                    tight = false;
                } else {
                    result += (long long)digit * powv[k - 1 - i];
                }
            }
            if (tight && xs.substr(k) >= s) result += 1;
            return result;
        };
        return count(finish) - count(start - 1);
    }
};
